/**
 * Project-specific adjustments applied on top of the webpack configuration
 * generated by generator-joplin.
 *
 * `npm run update` overwrites webpack.config.js. Keeping the adjustments here
 * means that after an update only the last line of webpack.config.js, which
 * loads this file, has to be restored.
 */

/**
 * Extra scripts that run inside a panel webview rather than being loaded
 * through require() by Joplin. They are emitted as a plain script with no
 * library export, because a webview has no `exports` object and the
 * generated CommonJS output would throw a ReferenceError once evaluated.
 */
const webviewScriptEntries = [
	'./src/gui/react/index.tsx',
];

/**
 * Removes the library export from the output of a single webpack
 * configuration when its entry is a webview script. Any other configuration
 * is returned unchanged.
 *
 * @param {object} config A webpack configuration produced by webpack.config.js.
 * @returns {object} The configuration to use for the build.
 */
function adjustConfig(config) {
	if (!webviewScriptEntries.includes(config.entry)) return config;

	const { library, libraryTarget, libraryExport, ...output } = config.output;
	return { ...config, output };
}

/**
 * Wraps the configuration factory exported by the generated webpack.config.js
 * so that every configuration it returns goes through adjustConfig().
 *
 * @param {function(object): object[]} generatedFactory The function exported by
 *   the generated webpack.config.js, which receives the webpack environment.
 * @returns {function(object): object[]} A factory with the same signature.
 */
module.exports = (generatedFactory) => (env) => generatedFactory(env).map(adjustConfig);
